def test_close_retires_a_pending_request_without_writing_mail(mesh: Mesh) -> None:
    mesh.run("send", "review-api", "worker", pane=PLANNER_PANE, stdin="review it\n")
    mesh.herdr.set("agent_sessions", {"worker": "sess-worker"})
    mesh.run("join", "worker", "--role", "worker", pane=WORKER_PANE)  # re-join records the session id

    result = mesh.run("close", "1", "planner", pane=WORKER_PANE)

    assert result.returncode == 0, result.stderr
    assert result.stdout.strip() == "closed 001-review-api from planner"
    line = [l for l in log_lines(mesh) if l["event"] == "closed"][-1]
    assert line["member"] == "worker"
    assert line["session"] == "sess-worker"
    assert line["id"] == "001-review-api"
    assert line["to"] == ["planner"]
    assert "time" in line
    assert not (mesh.inbox("planner") / "worker.001-review-api.reply").exists()  # no mail, ever
    status = mesh.run("status", "planner", pane=PLANNER_PANE)
    assert "001-review-api" not in status.stdout  # the requester's pending view drops it


