def test_prompt_box_state_classifies_herdr_shaped_screens(helper: ModuleType) -> None:
    def box(body: str) -> str:
        return f"※ transcript\n{'─' * 40}\n{body}\n{'─' * 40}\n  Model: glm | footer\n"

    assert helper.prompt_box_state(box("❯"), "claude") == "empty"
    assert helper.prompt_box_state(box("❯ draft text"), "claude") == "typing"
    assert helper.prompt_box_state(box("❯ wrapped draft\nsecond line"), "claude") == "typing"
    assert helper.prompt_box_state("no rules in this view\n", "claude") is None

    # claude renders its empty-composer suggestions dim and a human's typed
    # draft plain (the probe pane's captured bytes): the dim flag is what
    # tells suggestion text from typed text
    assert helper.prompt_box_state(box('❯ \x1b[0m\x1b[2mTry "how does <filepath> work?"\x1b[0m'), "claude") == "empty"
    assert helper.prompt_box_state(box("❯ \x1b[0m\x1b[2mTry \"fix lint errors\"\x1b[0m\n\x1b[0m\x1b[2mwrapped hint row\x1b[0m"), "claude") == "empty"
    assert helper.prompt_box_state(box("❯ fix the logi\x1b[0m\x1b[2mc the flaky login test\x1b[0m"), "claude") == "typing"
    # an SGR color's own arguments (38;2;R;G;B) carry a 2 that is not the dim
    # attribute - theme-colored text still reads as typed
    assert helper.prompt_box_state(box("❯ \x1b[0m\x1b[38;2;153;153;153m\x1b[48;2;55;55;55mtyped with theme colors\x1b[0m"), "claude") == "typing"

    # herdr's own rule semantic (detect/manifest.rs): a bare dash run of any
    # length is a rule, and so is a run of three or more with text after it
    assert helper.is_horizontal_rule("─" * 2) is True
    assert helper.is_horizontal_rule("─" * 3 + " agent config stuff ─") is True
    assert helper.is_horizontal_rule("─ x") is False
    assert helper.is_horizontal_rule("  plain text  ") is False


def test_prompt_box_state_classifies_cursor_screens(helper: ModuleType) -> None:
    # real cursor-agent 2026.10.28 bytes: the dim suggestion with its
    # reverse-video cursor letter is empty; plain text in the box is typing;
    # a screen with no 48;2 box rows at all is unseen
    assert helper.prompt_box_state(CURSOR_EMPTY_IDLE, "cursor") == "empty"
    assert helper.prompt_box_state(CURSOR_BUSY_EMPTY, "cursor") == "empty"
    assert helper.prompt_box_state(CURSOR_BUSY_QUEUED_POSTSEND, "cursor") == "empty"
    assert helper.prompt_box_state(CURSOR_WELCOME_EMPTY, "cursor") == "empty"
    assert helper.prompt_box_state(CURSOR_DRAFT_IDLE, "cursor") == "typing"
    assert helper.prompt_box_state(CURSOR_BUSY_DRAFT, "cursor") == "typing"
    assert helper.prompt_box_state(CURSOR_DRAFT_WRAPPED, "cursor") == "typing"
    assert helper.prompt_box_state(CURSOR_INFLIGHT_SUBMISSION, "cursor") == "typing"
    assert helper.prompt_box_state(CURSOR_TRUST_DIALOG, "cursor") is None


def test_cursor_detector_ignores_the_pane_header_row(helper: ModuleType) -> None:
    # U+276F is only the pane header row (❯ cursor-agent, colored, no box
    # background) - it rides in CURSOR_WELCOME_EMPTY's bytes and must never
    # match; the composer prompt glyph is → in every probed state
    import re as _re

    plain = _re.sub(r"\x1b\[[0-9;?]*[A-Za-z]", "", CURSOR_WELCOME_EMPTY)
    assert "❯ cursor-agent" in plain
    assert helper.prompt_box_state(CURSOR_WELCOME_EMPTY, "cursor") == "empty"


def test_cursor_detector_survives_a_theme_retint(helper: ModuleType) -> None:
    # declared transform (scenarios S7): retint the box rows and the
    # transcript-user rows - both carry 48;2 codes in these fixtures - so the
    # exact-code rule keeps box and transcript distinct
    def retint(screen: str) -> str:
        return (
            screen.replace("\x1b[48;2;43;41;59m", "\x1b[48;2;9;8;7m")
            .replace("\x1b[48;2;51;49;69m", "\x1b[48;2;7;8;9m")
        )

    assert helper.prompt_box_state(retint(CURSOR_EMPTY_IDLE), "cursor") == "empty"
    assert helper.prompt_box_state(retint(CURSOR_DRAFT_IDLE), "cursor") == "typing"
    # a retint of only the box code leaves the transcript code untouched -
    # still distinct, still typing
    only_box = CURSOR_DRAFT_IDLE.replace("\x1b[48;2;43;41;59m", "\x1b[48;2;9;8;7m")
    assert helper.prompt_box_state(only_box, "cursor") == "typing"


def test_is_cursor_pane_chrome_names_the_captured_shapes(helper: ModuleType) -> None:
    # the hand-written seam rows mirror the captured shapes: the panel
    # (borders, │ entries, │ helper) that carries a queued line's words, the
    # braille spinner, tips, the task count, the pct footer, box rows - all
    # chrome, never a consumer row
    chrome = helper.is_cursor_pane_chrome
    assert chrome(" ┌─ follow-ups ───────────────────────────────")
    assert chrome(" │ ○ transient inbox probe mno345")
    assert chrome(" │ enter steer · ↑ select/edit · esc cancel")
    assert chrome(" └────────────────────────────────────────────")
    assert chrome(" ⠘⠣ Running  14 tokens")
    assert chrome("  Tip: Use /skills to give Cursor specialized knowledge for tasks.")
    assert chrome("  1 task")
    assert chrome("  Claude Haiku 5.5 300K Low No Thinking · MAX · 10.4%")
    # the readback trims " \t%" from row ends - a narrow pane whose footer
    # ends at the pct must still classify chrome, or the drifting row reads
    # as a fresh consumer row (the false-delivered shape)
    assert chrome("  Claude Haiku 5.5 300K Low No Thinking · MAX · 10.4")
    assert chrome("  → Add a follow-up")
    assert not chrome("Noted: transient inbox probe mno345. No action taken.")


